mapper.select:
SELECT COUNT(1)
FROM fit_member
WHERE del_flag = '0'
  AND tenant_id = #{tenantId}
  AND mobile = #{mobile}

  AND member_id <> #{excludeMemberId}

SELECT c.course_id AS courseId, c.course_name AS courseName, c.course_type AS courseType, c.store_id AS storeId, s.store_name AS storeName, c.default_coach_id AS defaultCoachId, coach.coach_name AS coachName, c.duration_minutes AS durationMinutes, c.capacity, c.cover_url AS coverUrl, c.description, c.support_card_type AS supportCardType, c.status FROM fit_course c LEFT JOIN fit_store s ON s.store_id = c.store_id AND s.del_flag = '0' LEFT JOIN fit_coach coach ON coach.coach_id = c.default_coach_id AND coach.del_flag = '0' WHERE c.del_flag = '0' AND c.status = '0'
AND c.store_id = #{bo.storeId}
AND c.course_type = #{bo.courseType}
AND c.course_name LIKE CONCAT('%', #{bo.keyword}, '%')
ORDER BY c.course_id DESC

SELECT s.schedule_id AS scheduleId, s.store_id AS storeId, st.store_name AS storeName, s.course_id AS courseId, c.course_name AS courseName, c.course_type AS courseType, s.coach_id AS coachId, coach.coach_name AS coachName, s.schedule_date AS scheduleDate, s.start_time AS startTime, s.end_time AS endTime, s.capacity, s.reserved_count AS reservedCount, s.signed_count AS signedCount, (s.capacity - s.reserved_count) AS availableCount, s.schedule_status AS scheduleStatus, CASE WHEN r.reservation_id IS NOT NULL THEN TRUE ELSE FALSE END AS reservedByMe, r.reservation_id AS reservationId, r.reservation_status AS reservationStatus, cr.checkin_status AS checkinStatus FROM fit_course_schedule s INNER JOIN fit_course c ON c.course_id = s.course_id AND c.del_flag = '0' LEFT JOIN fit_store st ON st.store_id = s.store_id AND st.del_flag = '0' LEFT JOIN fit_coach coach ON coach.coach_id = s.coach_id AND coach.del_flag = '0' LEFT JOIN fit_course_reservation r ON r.schedule_id = s.schedule_id AND r.member_id = #{memberId} AND r.del_flag = '0' AND r.reservation_status <> 'cancelled'
LEFT JOIN fit_checkin_record cr ON cr.reservation_id = r.reservation_id AND cr.del_flag = '0' WHERE s.del_flag = '0' AND s.schedule_status <> 'cancelled' AND s.end_time > NOW() AND c.course_type NOT IN ('private', 'small')
AND s.store_id = #{bo.storeId}
AND s.course_id = #{bo.courseId}
AND c.course_type = #{bo.courseType}
AND s.coach_id = #{bo.coachId}
AND s.schedule_date = #{bo.scheduleDate}
ORDER BY s.start_time ASC

SELECT COUNT(1)
FROM fit_course_reservation
WHERE del_flag = '0'
  AND member_id = #{memberId}
  AND schedule_id = #{scheduleId}
  AND reservation_status = 'reserved'

SELECT p.plan_id AS planId, p.store_id AS storeId, st.store_name AS storeName, p.plan_name AS planName, p.plan_type AS planType, p.sale_price AS salePrice, p.original_price AS originalPrice, p.valid_days AS validDays, p.total_times AS totalTimes, p.gift_times AS giftTimes, p.stored_amount AS storedAmount, p.support_course_type AS supportCourseType, p.is_private_bind_coach AS isPrivateBindCoach, p.status FROM fit_card_plan p LEFT JOIN fit_store st ON st.store_id = p.store_id AND st.del_flag = '0' WHERE p.del_flag = '0' AND p.status = '0'
AND p.store_id = #{storeId}
ORDER BY p.sort_no ASC, p.plan_id DESC
